// Build prompt for Grok to research actual market outcome
const trade = $json;

// Calculate how many days ago the trade was created
const createdDate = new Date(trade.created_at);
const now = new Date();
const daysAgo = Math.floor((now - createdDate) / (1000 * 60 * 60 * 24));

const prompt = `You are a forex market researcher with access to historical price data.

**TASK: DETERMINE TRADE OUTCOME**

A trading position was opened ${daysAgo} day(s) ago. Research what actually happened in the market and determine if it was a WIN or LOSS.

**TRADE DETAILS:**
- Symbol: ${trade.symbol}
- Direction: ${trade.direction}
- Entry Price: ${parseFloat(trade.entry_price).toFixed(5)}
- Stop Loss: ${parseFloat(trade.stop_loss).toFixed(5)}
- Take Profit: ${parseFloat(trade.take_profit).toFixed(5)}
- Opened: ${trade.created_at} (${daysAgo} days ago)
- Original Rationale: ${trade.rationale}

**YOUR RESEARCH STEPS:**
1. Look up the actual historical price movement for ${trade.symbol} from ${trade.created_at} until now
2. Determine if the price hit the STOP LOSS or TAKE PROFIT first
3. If ${trade.direction} was:
   - LONG: Price going UP to take_profit = WIN, price going DOWN to stop_loss = LOSS
   - SHORT: Price going DOWN to take_profit = WIN, price going UP to stop_loss = LOSS
   - FLAT: Consider as LOSS (no action taken)
4. Find the actual exit price (whichever was hit first: SL or TP)
5. Calculate the profit/loss in pips

**RESPOND WITH ONLY THIS EXACT JSON (no markdown, no code blocks):**

{
  "trade_id": ${trade.id},
  "symbol": "${trade.symbol}",
  "is_win": true | false,
  "actual_exit_price": <the price where SL or TP was hit>,
  "pnl": <profit/loss in pips (positive for profit, negative for loss)>,
  "outcome_explanation": "Detailed explanation of what happened in the market:
    - What was the price movement after entry
    - Which level was hit (SL or TP)
    - Why this resulted in a win or loss
    - Any notable market events during this period",
  "research_notes": "Brief notes on the market data you analyzed"
}

**CRITICAL REQUIREMENTS:**
1. is_win must be boolean (true or false)
2. actual_exit_price must be a realistic price for ${trade.symbol}
3. pnl must be a number (positive for win, negative for loss)
4. Base your answer on ACTUAL market data research, not speculation
5. If you cannot determine the outcome with confidence, set is_win to false

**RESPOND WITH JSON ONLY:**`;

return {
  json: {
    trade_id: trade.id,
    symbol: trade.symbol,
    direction: trade.direction,
    entry_price: trade.entry_price,
    stop_loss: trade.stop_loss,
    take_profit: trade.take_profit,
    created_at: trade.created_at,
    prompt: prompt
  }
};

