// Parse Grok's outcome research response
let content = $json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('No content in Grok outcome response');
}

// Clean markdown
content = content.trim();
if (content.includes('```')) {
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '');
}

// Parse JSON
let outcome;
try {
  outcome = JSON.parse(content);
} catch (error) {
  throw new Error(`Failed to parse outcome JSON: ${error.message}\nContent: ${content}`);
}

// Validate required fields
if (outcome.trade_id === undefined) {
  throw new Error('Missing trade_id in outcome response');
}

if (typeof outcome.is_win !== 'boolean') {
  throw new Error(`is_win must be boolean, got: ${typeof outcome.is_win}`);
}

if (!outcome.actual_exit_price || isNaN(parseFloat(outcome.actual_exit_price))) {
  throw new Error('Invalid actual_exit_price');
}

if (outcome.pnl === undefined || isNaN(parseFloat(outcome.pnl))) {
  throw new Error('Invalid pnl value');
}

// Ensure proper types
outcome.trade_id = parseInt(outcome.trade_id);
outcome.actual_exit_price = parseFloat(outcome.actual_exit_price);
outcome.pnl = parseFloat(outcome.pnl);
outcome.is_win = Boolean(outcome.is_win);

return { json: outcome };

// Aggregate all updated trades
const updates = $input.all();

if (updates.length === 0) {
  return {
    json: {
      total_checked: 0,
      wins: 0,
      losses: 0,
      message: 'No trades were updated'
    }
  };
}

const wins = updates.filter(u => u.json.is_win === true).length;
const losses = updates.filter(u => u.json.is_win === false).length;
const winRate = ((wins / updates.length) * 100).toFixed(1);

const summary = {
  total_checked: updates.length,
  wins: wins,
  losses: losses,
  win_rate: winRate + '%',
  timestamp: new Date().toISOString(),
  details: updates.map(u => ({
    id: u.json.id,
    symbol: u.json.symbol,
    direction: u.json.direction,
    outcome: u.json.is_win ? 'WIN' : 'LOSS',
    pnl: parseFloat(u.json.pnl).toFixed(2)
  }))
};

return { json: summary };

// Build summary email for outcome updates
const summary = $json;

if (summary.total_checked === 0) {
  return {
    json: {
      subject: '✅ Daily Outcome Update - No Trades to Check',
      html: `
<!DOCTYPE html>
<html>
<body style="font-family: Arial; padding: 20px;">
  <h2>Daily Trade Outcome Update</h2>
  <p>No trades required outcome verification today.</p>
  <p><small>${new Date().toLocaleString()}</small></p>
</body>
</html>
      `
    }
  };
}

const winEmoji = '✅';
const lossEmoji = '❌';

const detailRows = summary.details.map(d => `
  <tr style="border-bottom: 1px solid #e2e8f0;">
    <td style="padding: 12px;">${d.outcome === 'WIN' ? winEmoji : lossEmoji} ${d.symbol}</td>
    <td style="padding: 12px;">${d.direction}</td>
    <td style="padding: 12px; color: ${d.outcome === 'WIN' ? '#10b981' : '#ef4444'}; font-weight: bold;">${d.outcome}</td>
    <td style="padding: 12px; color: ${parseFloat(d.pnl) >= 0 ? '#10b981' : '#ef4444'};">${parseFloat(d.pnl) >= 0 ? '+' : ''}${d.pnl} pips</td>
  </tr>
`).join('');

const html = `
<!DOCTYPE html>
<html>
<head>
<style>
  body { font-family: Arial, sans-serif; background: #f5f5f5; padding: 20px; margin: 0; }
  .container { background: white; border-radius: 10px; padding: 30px; max-width: 700px; margin: 0 auto; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
  .header { background: linear-gradient(135deg, #3b82f6 0%, #1e40af 100%); color: white; padding: 20px; border-radius: 8px; text-align: center; margin-bottom: 25px; }
  .stats { display: flex; justify-content: space-around; margin: 25px 0; }
  .stat-box { text-align: center; padding: 20px; background: #f8fafc; border-radius: 8px; flex: 1; margin: 0 10px; }
  .stat-number { font-size: 32px; font-weight: bold; margin: 10px 0; }
  .stat-label { color: #64748b; font-size: 14px; }
  .wins { color: #10b981; }
  .losses { color: #ef4444; }
  .win-rate { color: #3b82f6; }
  table { width: 100%; border-collapse: collapse; margin: 20px 0; }
  th { background: #f1f5f9; padding: 12px; text-align: left; font-weight: 600; color: #475569; }
</style>
</head>
<body>
<div class="container">
  <div class="header">
    <h1>📊 Daily Trade Outcome Update</h1>
    <p style="margin: 5px 0 0 0; opacity: 0.9;">${new Date().toLocaleDateString()}</p>
  </div>

  <div class="stats">
    <div class="stat-box">
      <div class="stat-number">${summary.total_checked}</div>
      <div class="stat-label">Trades Checked</div>
    </div>
    <div class="stat-box">
      <div class="stat-number wins">${summary.wins}</div>
      <div class="stat-label">Wins ${winEmoji}</div>
    </div>
    <div class="stat-box">
      <div class="stat-number losses">${summary.losses}</div>
      <div class="stat-label">Losses ${lossEmoji}</div>
    </div>
    <div class="stat-box">
      <div class="stat-number win-rate">${summary.win_rate}</div>
      <div class="stat-label">Win Rate</div>
    </div>
  </div>

  <h3 style="margin-top: 30px; color: #1e293b;">Trade Details:</h3>
  <table>
    <thead>
      <tr>
        <th>Symbol</th>
        <th>Direction</th>
        <th>Outcome</th>
        <th>P&L</th>
      </tr>
    </thead>
    <tbody>
      ${detailRows}
    </tbody>
  </table>

  <div style="background: #eff6ff; border-left: 4px solid #3b82f6; padding: 15px; margin-top: 25px; border-radius: 4px;">
    <p style="margin: 0; color: #1e40af;"><strong>ℹ️ Note:</strong> These outcomes have been added to the database and will be used as historical context (RAG) for future trade analysis to improve pattern recognition.</p>
  </div>

  <div style="text-align: center; color: #94a3b8; font-size: 13px; margin-top: 30px; padding-top: 20px; border-top: 1px solid #e2e8f0;">
    <p>Automated Outcome Verification System</p>
    <p>${summary.timestamp}</p>
  </div>
</div>
</body>
</html>
`;

const subject = `📊 Daily Update: ${summary.total_checked} Trades Verified - ${summary.win_rate} Win Rate`;

return {
  json: {
    subject: subject,
    html: html
  }
};
